async def test_update_order_data_skipped_on_fetch_error(db_session):
    listing, _ = await seed_listing(db_session, intent=Intent.buy)
    state, status = await scanner_service.update_order_data(
        db_session, Scanner(bp=RaisingBP()), listing
    )
    assert state is None and status == "skipped"


async def test_update_order_data_inactive_when_users_order_missing(db_session):
    listing, _ = await seed_listing(db_session, intent=Intent.buy)
    bp = FakeBP(snapshots={"Key": [snap("comp", 10)]})
    state, status = await scanner_service.update_order_data(
        db_session, Scanner(bp=bp), listing
    )
    assert state is None and status == "skipped"
    assert listing.status == "inactive"


async def test_refresh_order_states_updates_tracker(db_session, monkeypatch):
    async def no_sleep(_):
        return None

    monkeypatch.setattr(scanner_service.asyncio, "sleep", no_sleep)
    listing, _ = await seed_listing(db_session, intent=Intent.buy)
    bp = FakeBP(
        snapshots={
            "Key": [
                snap(USER, 5),
                snap("comp", 10),
                snap("seller", 2, intent=Intent.sell),
            ],
        }
    )
    await scanner_service.refresh_order_states(
        db_session, Scanner(bp=bp), buy_sync_tracker, Intent.buy
    )
    assert buy_sync_tracker.total == 1
    assert buy_sync_tracker.current == 1
    assert buy_sync_tracker.synced_ids == [listing.id]


async def test_sync_and_scan_orders_end_to_end(db_session, monkeypatch):
    async def no_sleep(_):
        return None

    monkeypatch.setattr(scanner_service.asyncio, "sleep", no_sleep)
    bp = FakeBP(
        snapshots={
            "Key": [
                snap(USER, 5),
                snap("comp", 10),
                snap("seller", 2, intent=Intent.sell),
            ],
        }
    )
    bp.pages = [([BPListing.from_api(bp_listing_dict())], None)]
    await scanner_service.sync_and_scan_orders(
        db_session, bp, Scanner(bp=bp), buy_sync_tracker, Intent.buy
    )
    assert buy_sync_tracker.synced_ids == ["L1"]
    stored = await crud.get_stored_listings(db_session)
    assert len(stored) == 1
    assert len(await crud.get_stored_buyorder_state_histories(db_session)) == 0
